<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { getDevices } from '@/api/device'; import { getLabs } from '@/api/lab'; import { getCategories } from '@/api/category'; import { getUsers } from '@/api/user'
import { formatCurrency, formatNumber } from '@/utils/format'; import EChart from '@/components/EChart.vue'; import type { EChartsOption } from 'echarts'
const router = useRouter(); const devices = ref<Awaited<ReturnType<typeof getDevices>>>([]); const labs = ref<Awaited<ReturnType<typeof getLabs>>>([]); const categories = ref<Awaited<ReturnType<typeof getCategories>>>([]); const users = ref<Awaited<ReturnType<typeof getUsers>>>([])
onMounted(async () => { [devices.value, labs.value, categories.value, users.value] = await Promise.all([getDevices(), getLabs(), getCategories(), getUsers()]) })
const total = computed(() => devices.value.reduce((sum, d) => sum + (d.price || 0), 0)); const countBy = (key: 'deviceStatus'|'categoryName'|'labName') => Object.entries(devices.value.reduce<Record<string, number>>((a, d) => { const k = d[key] || '未分类'; a[k] = (a[k] || 0) + 1; return a }, {})).map(([name, value]) => ({ name, value }))
const pie = computed<EChartsOption>(() => ({ tooltip: { trigger: 'item' }, series: [{ type: 'pie', radius: '60%', data: countBy('deviceStatus') }] })); const bar = computed<EChartsOption>(() => ({ xAxis: { type: 'category', data: countBy('categoryName').map(x => x.name) }, yAxis: { type: 'value' }, series: [{ type: 'bar', data: countBy('categoryName').map(x => x.value), itemStyle: { color: '#409eff' } }] }))
</script>
<template><div class="page"><div class="page-header"><h2>首页仪表盘</h2></div><div class="stat-grid"><div class="card">设备总数<div class="stat-value">{{ formatNumber(devices.length) }}</div></div><div class="card">实验室总数<div class="stat-value">{{ formatNumber(labs.length) }}</div></div><div class="card">设备分类总数<div class="stat-value">{{ formatNumber(categories.length) }}</div></div><div class="card">设备总价值<div class="stat-value">{{ formatCurrency(total) }}</div></div></div><div class="chart-grid"><div class="card"><h3>设备状态分布</h3><EChart :option="pie" /></div><div class="card"><h3>分类设备数量</h3><EChart :option="bar" /></div></div><div class="card" style="margin-top:16px"><h3>快捷操作</h3><el-button type="primary" @click="router.push('/devices')">新增设备</el-button><el-button @click="router.push('/labs')">实验室管理</el-button><el-button @click="router.push('/categories')">分类管理</el-button><el-button @click="router.push('/users')">用户管理（{{ users.length }}）</el-button></div></div></template>
